def find(items, target):
    for i, value in enumerate(items):
        if value == target:
            return i
    return -1

print(find([8, 3, 5, 1], 5))

def binary_search(items, target):
    left, right = 0, len(items) - 1
    while left <= right:
        mid = (left + right) // 2
        if items[mid] == target:
            return mid
        if items[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

print(binary_search([1, 3, 5, 7, 9], 7))

